#!/usr/bin/env node
// One-time import that starts the Enterprise Excellence findings register.
// It reads every finding already recorded in qa/ (engineering-quality-findings.md,
// defect-register.md, ux-improvement-register.md), keeps their IDs, and adds the findings
// discovered in Phase 1 (B-series). The result, qa/enterprise-excellence/findings.json, is the
// one source of truth from here on: later phases edit that file and rerun
// qa/tools/excellence-docs.mjs to rebuild findings-register.md. Do not rerun this import after
// findings.json has been edited by hand, unless --force is given.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const OUT = path.join(root, 'qa/enterprise-excellence/findings.json');
if (fs.existsSync(OUT) && !process.argv.includes('--force')) { console.error('findings.json exists. Edit it directly, or pass --force to rebuild it from the old registers.'); process.exit(1); }
const read = (f) => fs.readFileSync(path.join(root, f), 'utf8');
const cells = (l) => l.split('|').slice(1, -1).map((x) => x.trim());
const SEV = { Critical: 'P0', High: 'P1', Medium: 'P2', Low: 'P3', Unknown: 'P2' };
const THEME = { E: 'Phase 2: architecture and code quality', S: 'Sales and customer operations', I: 'Inventory and purchasing', M: 'Manufacturing and processing', F: 'Shipping and financial operations', X: 'Enterprise experience', U: 'Phase 9: user experience', D: 'By subject (see the finding)' };
const findings = [];

// ── engineering-quality-findings.md ─────────────────────────────────────────────────────────
{
  const text = read('qa/engineering-quality-findings.md'); const disp = {}; let mode = '';
  const rows = [];
  for (const l of text.split('\n')) {
    if (/^\| ID \| Module/.test(l)) { mode = 'f'; continue; } if (/^\| ID \| Disposition/.test(l)) { mode = 'd'; continue; }
    if (!l.startsWith('|')) { mode = ''; continue; } if (/^\|[-| ]+\|$/.test(l)) continue;
    const c = cells(l);
    if (mode === 'f' && /^[A-Z]-\d/.test(c[0])) rows.push(c);
    if (mode === 'd') for (const id of c[0].split(/,\s*/)) if (/^[A-Z]-\d/.test(id)) disp[id.trim()] = { disposition: c[1], owner: c[2], dependsOn: c[3], doneWhen: c[4] };
  }
  for (const c of rows) {
    const [id, module, category, actual, expected, evidence, impact, risk, statusText, proof] = c; const d = disp[id];
    let status;
    if (/^Fixed(?! in part| pending)|^Mitigated and fixed/.test(statusText)) status = proof ? 'VERIFIED FIXED' : 'FIXED — NOT VERIFIED';
    else if (/decision|owner/i.test(`${statusText} ${d?.disposition || ''}`)) status = 'REQUIRES BUSINESS DECISION';
    else if (/Blocked/i.test(d?.disposition || '')) status = 'BLOCKED';
    else if (/Deferred|Accepted/i.test(d?.disposition || '')) status = 'DEFERRED WITH JUSTIFICATION';
    else if (/in part|Partly|Mitigated/i.test(statusText)) status = 'IN PROGRESS';
    else status = 'OPEN';
    findings.push({ id, discovered: '2026-11-13', source: 'qa/engineering-quality-findings.md', module, workflow: '', severity: SEV[risk] || 'P2', category, where: evidence, evidence, expected, actual, cause: '', impact, dependencies: d?.dependsOn || '', correction: d?.disposition || '', requiredTests: d?.doneWhen || '', phase: THEME[id[0]] || '', status, statusNote: statusText, verification: /FIXED/.test(status) ? proof : '' });
  }
}
// ── defect-register.md ──────────────────────────────────────────────────────────────────────
{
  let sect = '';
  for (const l of read('qa/defect-register.md').split('\n')) {
    if (l.startsWith('## ')) { sect = l.slice(3); continue; }
    if (!/^\| D-/.test(l)) continue; const c = cells(l);
    if (/^Fixed/.test(sect)) findings.push({ id: c[0], discovered: '2026-11-12', source: 'qa/defect-register.md', module: '', workflow: '', severity: c[1], category: 'Defect', where: '', evidence: c[5] || '', expected: '', actual: c[2], cause: c[3], impact: '', dependencies: '', correction: c[4], requiredTests: '', phase: 'Done before the program', status: c[5] ? 'VERIFIED FIXED' : 'FIXED — NOT VERIFIED', statusNote: 'Fixed in the first audit', verification: c[5] || '' });
    else if (/business/.test(sect)) findings.push({ id: c[0], discovered: '2026-11-12', source: 'qa/defect-register.md', module: '', workflow: '', severity: c[1], category: 'Missing function', where: '', evidence: '', expected: '', actual: c[2], cause: '', impact: '', dependencies: c[3], correction: c[3], requiredTests: '', phase: THEME.D, status: 'REQUIRES BUSINESS DECISION', statusNote: 'Open: needs something from the business', verification: '' });
    else findings.push({ id: c[0], discovered: '2026-11-12', source: 'qa/defect-register.md', module: '', workflow: '', severity: c[1], category: 'Defect', where: '', evidence: '', expected: '', actual: c[2], cause: '', impact: '', dependencies: '', correction: c[3] || '', requiredTests: '', phase: THEME.D, status: 'OPEN', statusNote: 'Open: engineering work', verification: '' });
  }
}
// ── ux-improvement-register.md ──────────────────────────────────────────────────────────────
for (const l of read('qa/ux-improvement-register.md').split('\n')) {
  if (!/^\| U-/.test(l)) continue; const c = cells(l);
  const status = /^Fixed/.test(c[3]) ? 'VERIFIED FIXED' : /decision|owner/i.test(c[3]) ? 'REQUIRES BUSINESS DECISION' : /Labelled|Mitigated/i.test(c[3]) ? 'IN PROGRESS' : 'OPEN';
  findings.push({ id: c[0], discovered: '2026-11-13', source: 'qa/ux-improvement-register.md', module: c[1], workflow: '', severity: 'P3', category: 'User experience', where: c[1], evidence: '', expected: '', actual: c[2], cause: '', impact: '', dependencies: '', correction: '', requiredTests: '', phase: THEME.U, status, statusNote: c[3], verification: status === 'VERIFIED FIXED' ? c[3] : '' });
}

// ── Phase 1 findings (B-series) ─────────────────────────────────────────────────────────────
const PROBE = 'qa/sim/baseline-probe.mjs';
const B = (n, o) => findings.push({ id: `B-${String(n).padStart(3, '0')}`, discovered: '2026-11-13', source: 'Phase 1 discovery', workflow: '', cause: '', dependencies: '', statusNote: '', verification: '', ...o });
